local _, WFJ = ...
WFJ.Data.add("quest", {
  [79483] = { "Dolci rubati del Grande Inverno", "Trova l'investigatore della Masseria Buongusto scomparso nelle regioni innevate delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Senti... non voglio rovinare la magia della stagione, ma la Masseria Buongusto avrebbe bisogno di un po' di aiuto, del tipo che voi avventurieri siete famosi per dare.\n\nCi manca un'importante spedizione di dolci che doveva rifornirci per la stagione, e ora ci manca anche l'agente della Masseria Buongusto che avevamo mandato sul campo a cercarla! Ti prego: secondo l'ultima notizia, la spedizione era nelle ⟦Alterac Mountains=Montagne d'Alterac⟧, ed è lì che il nostro uomo è andato a cercarla.\n\nVedi se sono lì, sani e salvi!", nil, nil, 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, nil, "...mm" },
  [79492] = { "Metzen la Renna", "Trova Metzen la Renna. Usa le note che ti sono state date per capire dove lo tengono prigioniero.\n\nQuando trovi Metzen, tieni con te il ⟦Pouch of Reindeer Dust=Sacchetto di Polvere di Renna⟧, così potrai cospargerlo con un po' di polvere: dovrebbe liberarlo dalle catene della prigionia.\n\nUna volta liberato Metzen, riporta il ⟦Pouch of Reindeer Dust=Sacchetto di Polvere di Renna⟧ a Wulmort Jinglepocket a ⟦Ironforge=Forgiardente⟧.", "DISASTRO! Hanno rapito Metzen la Renna!\n\nMetzen è una delle otto renne di Babbo Inverno, ed è proprietà della Masseria Buongusto. Abbiamo ricevuto non una ma DUE lettere di riscatto da gruppi che sostengono di avere Metzen. Con le feste ormai in pieno svolgimento, qui siamo a corto di monete! Ti prego, trova Metzen e riportacelo!\n\nControlla le lettere di riscatto per trovare indizi, e cospargilo con questa polvere di renna: lo libererà da qualsiasi catena!\n\nTi prego, sbrigati!", nil, nil, 0x9cd6daf6, 0xcf081272, 0x3da2b74f, nil, nil, "...mm" },
  [79495] = { "Metzen la Renna", "Trova Metzen la Renna. Usa le note che ti sono state date per trovare indizi su dove lo tengono prigioniero.\n\nQuando trovi Metzen, tieni con te il ⟦Pouch of Reindeer Dust=Sacchetto di Polvere di Renna⟧, così potrai spargergli addosso un po' di polvere: dovrebbe liberarlo dalle catene della prigionia.\n\nUna volta liberato Metzen, riporta il ⟦Pouch of Reindeer Dust=Sacchetto di Polvere di Renna⟧ a Kaymard Copperpinch, a Orgrimmar.", "È successo un DISASTRO! Metzen la Renna è stato rapito!\n\nMetzen è una delle otto renne di Babbo Inverno, e appartiene alla Masseria Buongusto. Abbiamo ricevuto non una ma DUE lettere di riscatto da gruppi che sostengono di avere Metzen. Con le feste in pieno svolgimento, qui siamo a corto di soldi in cassa! Ti prego, trova Metzen e riportacelo!\n\nControlla le lettere di riscatto per trovare indizi, e spargigli addosso questa polvere di renna: lo libererà da qualsiasi catena!\n\nTi prego, sbrigati!", nil, nil, 0x9cd6daf6, 0xa38abc5d, 0x80df7c2b, nil, nil, "...mm" },
  [79637] = { "Un ⟦Ticking Present=Regalo Ticchettante⟧", nil, nil, nil, nil, 0xd9f880a5, nil, nil, nil, nil, ".mmmm" },
